declare(strict_types=1);
/** Prepared text only. Approval, duration decisions and real processor details remain with the owner. */
function nd_portal_draft():array{
 $d=['operator_name'=>'Сухарева Наталья Владимировна','operator_address'=>'Романово, Калининградская область','contact'=>'admin@neurodelo.pro; Telegram @minden2006; личная ссылка MAX на neurodelo.pro','legal_basis'=>'Обработка необходимого минимума для подготовки и исполнения договора по обращению самого субъекта — пункт 5 части 1 статьи 6 Федерального закона №152-ФЗ. Отдельное добровольное согласие используется для обработки, требующей согласия; обязательные сведения о расчётах сохраняются при наличии применимой обязанности по закону. Рекламные рассылки в этот процесс не входят. Публикация отзыва, имени, изображения или материалов заказа требует самостоятельного добровольного разрешения на точное содержание; отказ не влияет на заказ.','retention'=>'Сведения используются до достижения конкретной цели. Договорные и расчётные доказательства сохраняются, пока существует проверенное договорное или установленное законом основание. Дата проверки хранения устанавливается отдельно для категории документов; автоматического удаления по единому сроку нет. При споре или незавершённых обязанностях удаление удерживается. После отпадения оснований оператор рассматривает прекращение обработки и уничтожение в применимые сроки статьи 21 Федерального закона №152-ФЗ. [Уточнить: перечень категорий, применимые к самозанятому обязательные сроки и порядок уничтожения с учётом фактических резервных копий].','processors'=>'Приложение и приватные файлы размещены в существующем аккаунте SpaceWeb; транзакционная почта отправляется через smtp.spaceweb.ru. Пароль почты хранится только в приватных настройках. MAX используется для уведомлений владельцу без текста заявки и для добровольной привязки аккаунта при включённой функции. При личном обращении в мессенджер действуют также условия соответствующего сервиса. [Уточнить: полные сведения о договорном обработчике SpaceWeb, фактические места баз и резервных копий в РФ, состав поручения обработки, применимые уведомления Роскомнадзору и сведения о трансграничной передаче, если она фактически имеется].'];
 $p=ocs_prepare_policy($d);$p['policy_text'].="\n\nПрактические правила сервиса. Публичная регистрация отключена. До оплаты обмен реквизитами, отдельными PDF и копиями подписанных бумажных документов выполняется по ограниченной ссылке с возможностью отзыва и сроком действия. Загрузка копии не подтверждает подлинность подписи: её отдельно проверяет исполнитель. После проверки первого согласованного поступления и выполнения настроек отправляется одноразовое приглашение. Пароль кабинета хранится в виде стойкого хеша; рабочие сессии ограничены по времени. Привязка MAX не заменяет оплату или согласие. Срок рабочего доступа к конкретному заказу может ограничиваться только прямо согласованными условиями; истечение не удаляет договорные документы и не отключает другие заказы.\n\nКатегории: потенциальные и действующие заказчики и их уполномоченные представители. Данные: имя, контактный email/телефон/мессенджер по выбору, предоставленные необходимые реквизиты, требования и материалы заказа, сообщения, решения, сканы/фото подписанных документов, сведения о ручной сверке оплаты и копии официальных чеков, технические идентификаторы безопасности и, при добровольной привязке, проверенный идентификатор MAX. Специальные категории и биометрическая идентификация не используются по назначению сервиса. Не направляйте лишние персональные данные и пароли в обычные формы и переписку.\n\nПрава: запросить сведения об обработке, уточнение, ограничение или прекращение при наличии оснований, отозвать согласие и обратиться в Роскомнадзор либо суд. Запрос направляется оператору по указанному контакту. Отзыв не отменяет самостоятельные законные основания хранения договора и расчётных доказательств. Экспорт и уничтожение рассматриваются с проверкой полномочий заявителя и оставшихся обязанностей. Обработка не используется для решений, порождающих юридические последствия исключительно автоматически. Платёж, бумажные копии, коммерческие условия и передача проверяются владельцем.\n\nМеры защиты: разграничение по аккаунтам/заказам, закрытое файловое хранилище, HTTPS, контроль подмены версий, CSRF, ограничение частоты, контрольные суммы и журнал решений. Эти меры не заменяют организационные обязанности оператора.";
 $content=array_intersect_key($p,array_flip(['version','policy_text','consent_text']));$p['hash']=hash('sha256',json_encode($content,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$p['review_notes']=['Подтвердить актуальность адреса оператора и необходимые реквизиты.','Разрешить отмеченные поля без выдуманных сроков или утверждений о размещении.','Проверить применимость уведомления оператором Роскомнадзора.'];$p['sources']=[['url'=>'https://mintrud.gov.ru/docs/laws/130','scope'=>'152-ФЗ: основания, раздельное согласие, меры защиты, прекращение обработки'],['url'=>'https://publication.pravo.gov.ru/document/0001202607260024','scope'=>'265-ФЗ от26.07.2026: изменение статьи12 о трансграничной передаче'],['url'=>'https://publication.pravo.gov.ru/Document/View/0001202104210039','scope'=>'Приказ Роскомнадзора18: отдельное согласие на распространение'],['url'=>'https://dev.max.ru/docs/webapps/validation','scope'=>'Техническая проверка идентификатора MAX']];$p['sources'][]=['url'=>'https://base.garant.ru/414652990/','scope'=>'Актуальность265-ФЗ проверена по правовой базе; прямая загрузка официального портала недоступна исследовательскому инструменту'];$p['research_checked_on']='2026-10-30';return $p;
}
function nd_prepare_portal_draft():bool{return ocs_locked(function(){$s=ocs_read();if(ocs_active_policy($s)||isset($s['draft_policy']))return false;$p=nd_portal_draft();ocs_policy_write($p);$s['draft_policy']=$p['version'];ocs_save($s,'prepared_product_policy_draft',['version'=>$p['version'],'hash'=>$p['hash'],'approved'=>false]);return true;});}
